/* Modelo de invitación: xv-clasico */
(window.__INV=window.__INV||{})["xv-clasico"]="<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Mis XV Años<\/title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Pinyon+Script&family=Cormorant+SC:wght@500;600&family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Great+Vibes&family=Cinzel:wght@400;500;600&family=Parisienne&family=Marcellus&family=Marcellus+SC&family=Sacramento&family=Josefin+Sans:wght@400;600&family=Imperial+Script&family=Playfair+Display+SC:wght@400;700&family=Playfair+Display:ital,wght@0,400;0,600;1,400&family=Dancing+Script:wght@500;700&family=Quicksand:wght@500;600&display=swap\">\n<script id=\"cfg\" type=\"application/json\">\n{\n \"modelo\": \"xv-clasico\",\n \"paleta\": \"azul\",\n \"letra\": \"elegante\",\n \"portada\": \"marco\",\n \"secciones\": {\n  \"sobre\": true,\n  \"musica\": true,\n  \"recuerdos\": true,\n  \"galeria\": true,\n  \"ceremonia\": true,\n  \"recepcion\": true,\n  \"itinerario\": true,\n  \"mensaje\": true,\n  \"vestimenta\": true,\n  \"sobres\": true,\n  \"libres\": true,\n  \"confirmacion\": true\n },\n \"nombre\": \"Isabella\",\n \"subtitulo\": \"Mis XV Años\",\n \"sello\": \"XV\",\n \"textoBendicion\": \"Con la bendición de Dios y de mis padres\",\n \"papa\": \"Roberto Morales\",\n \"mama\": \"Daniela Castillo\",\n \"textoInvitacion\": \"tengo el honor de invitarte a celebrar mis XV años.\",\n \"nombreCompleto\": \"Isabella María Morales Castillo\",\n \"textoFecha\": \"Acompáñame a celebrar este\",\n \"fecha\": \"2027-03-20\",\n \"hora\": \"17:00\",\n \"tituloGaleria\": \"Mis recuerdos\",\n \"ceremonia\": {\n  \"titulo\": \"Ceremonia religiosa\",\n  \"lugar\": \"Parroquia San José\",\n  \"hora\": \"15:30\",\n  \"waze\": \"https://www.waze.com/es/live-map/\",\n  \"maps\": \"https://www.google.com/maps/search/?api=1&query=Ciudad%20de%20Guatemala\"\n },\n \"recepcion\": {\n  \"titulo\": \"Recepción\",\n  \"lugar\": \"Salón de eventos Jardín Real\",\n  \"hora\": \"17:00\",\n  \"waze\": \"https://www.waze.com/es/live-map/\",\n  \"maps\": \"https://www.google.com/maps/search/?api=1&query=Ciudad%20de%20Guatemala\"\n },\n \"itinerario\": [\n  {\n   \"hora\": \"17:00\",\n   \"actividad\": \"Recepción\"\n  },\n  {\n   \"hora\": \"18:00\",\n   \"actividad\": \"Entrada\"\n  },\n  {\n   \"hora\": \"18:30\",\n   \"actividad\": \"Vals\"\n  },\n  {\n   \"hora\": \"19:00\",\n   \"actividad\": \"Brindis\"\n  },\n  {\n   \"hora\": \"19:30\",\n   \"actividad\": \"Cena\"\n  },\n  {\n   \"hora\": \"20:30\",\n   \"actividad\": \"Fiesta\"\n  },\n  {\n   \"hora\": \"22:00\",\n   \"actividad\": \"Pastel\"\n  },\n  {\n   \"hora\": \"23:30\",\n   \"actividad\": \"Despedida\"\n  }\n ],\n \"mensaje\": {\n  \"parrafos\": [\n   \"Hoy mi corazón está lleno de\\n*ilusión y gratitud,*\\ny le doy gracias a *Dios*\\npor permitirme vivir este día tan soñado.\",\n   \"A mis *papás*, gracias por cuidarme, guiarme y llenarme de amor en cada etapa de mi vida.\",\n   \"A mis *padrinos*, gracias por acompañarme y ser parte de este momento tan especial.\",\n   \"Y a todos mis *seres queridos*, gracias por celebrar conmigo el comienzo de una nueva etapa.\"\n  ],\n  \"despedida\": \"Con todo mi cariño,\",\n  \"firma\": \"Isabella\"\n },\n \"vestimenta\": {\n  \"tipo\": \"Formal\",\n  \"nota\": \"Con mucho cariño, les pedimos evitar el tono azul marino, ya que está reservado especialmente para la quinceañera.\"\n },\n \"sobres\": {\n  \"titulo\": \"Lluvia de sobres\",\n  \"texto1\": \"Tenerte conmigo en este día tan especial significa más de lo que imaginas: tu compañía es el regalo más valioso para mí.\",\n  \"texto2\": \"Si deseas obsequiarme algo, habrá sobres disponibles el día del evento.\"\n },\n \"libres\": [\n  {\n   \"titulo\": \"Sección libre\",\n   \"texto\": \"Aquí puedes agregar lo que quieras: hashtag para fotos, hospedaje, recomendaciones o un aviso especial.\"\n  }\n ],\n \"contactos\": [\n  {\n   \"rol\": \"mama\",\n   \"titulo\": \"Mamá\",\n   \"nombre\": \"Daniela\",\n   \"tel\": \"00000000\"\n  },\n  {\n   \"rol\": \"papa\",\n   \"titulo\": \"Papá\",\n   \"nombre\": \"Roberto\",\n   \"tel\": \"00000000\"\n  },\n  {\n   \"rol\": \"quince\",\n   \"titulo\": \"Quinceañera\",\n   \"nombre\": \"Isabella\",\n   \"tel\": \"00000000\"\n  }\n ],\n \"mensajeWA\": \"Hola, confirmo mi asistencia a los XV años de Isabella\",\n \"agradecimiento\": \"Gracias por formar parte de uno de los capítulos más hermosos de mi vida.\",\n \"fotos\": {\n  \"portada\": \"\",\n  \"recuerdos\": [\n   \"\",\n   \"\",\n   \"\"\n  ],\n  \"galeria\": [\n   \"\",\n   \"\",\n   \"\"\n  ]\n },\n \"cancion\": \"\"\n}\n<\/script>\n<script>\nwindow.CFG=JSON.parse(document.getElementById('cfg').textContent);\ndocument.documentElement.dataset.paleta=CFG.paleta||'azul';\ndocument.documentElement.dataset.letra=CFG.letra||'elegante';\nif(CFG.colores){for(const k in CFG.colores) document.documentElement.style.setProperty('--'+k,CFG.colores[k]);}\n<\/script>\n<style>\n*,*::before,*::after{box-sizing:border-box}html,body{margin:0}img{max-width:100%}[hidden]{display:none!important}\n\n/* Layout: columna de papel con bordes rasgados metálicos sobre fondo acuarela. Colores = paleta (data-paleta en <html>) */\n:root{\n  --bg-1:#1b335a;--bg-2:#1e355e;--bg-3:#2e4c7d;--bg-4:#3b5681;--fab-hi:#2a4f9c;--fab-mid:#1c3577;--fab-lo:#122252;--fab-glow:#3f6cc4;--sparkle:#c9d8f5;--ink:#193569;--ink-dark:#122252;--btn:#355587;--play:#5384a6;--paper:#e9edf7;--paper-2:#dfe5f1;--paper-hi:#f6f8fc;--m-hi:#f4f6f9;--m-mid:#cbd0d7;--m-lo:#9aa3b0;--m-dark:#7d8796;--m-text:#4a5566;--sh:18,34,82;\n  --silver:var(--m-mid);\n  --f-script:\"Pinyon Script\",\"Great Vibes\",cursive;\n  --f-caps:\"Cormorant SC\",\"Cormorant Garamond\",Georgia,serif;\n  --f-body:\"Cormorant Garamond\",Georgia,serif;\n  color-scheme:light;\n}\n:root[data-paleta=\"rosa\"]{--bg-1:#a8606f;--bg-2:#b56e7d;--bg-3:#c7838f;--bg-4:#d89ca6;--fab-hi:#eaa6b6;--fab-mid:#d07f93;--fab-lo:#a85a6e;--fab-glow:#f6c6d2;--sparkle:#fff0f4;--ink:#7a3d4c;--ink-dark:#5e2a37;--btn:#b0627a;--play:#cf8a9b;--paper:#fbf0f2;--paper-2:#f3dfe4;--paper-hi:#fff8fa;--m-hi:#fbf3dc;--m-mid:#e2c98a;--m-lo:#b8923f;--m-dark:#8c6a26;--m-text:#5e4614;--sh:94,42,55;}\n:root[data-paleta=\"verde\"]{--bg-1:#0f3d33;--bg-2:#12463a;--bg-3:#1b5c4c;--bg-4:#2a6e5c;--fab-hi:#1f7a62;--fab-mid:#145c49;--fab-lo:#0b3d30;--fab-glow:#3fae8c;--sparkle:#c9f0e0;--ink:#154a3c;--ink-dark:#0b3329;--btn:#2a7a64;--play:#4f9c86;--paper:#edf4f0;--paper-2:#dde9e3;--paper-hi:#f7fbf9;--m-hi:#fbf3dc;--m-mid:#e2c98a;--m-lo:#b8923f;--m-dark:#8c6a26;--m-text:#5e4614;--sh:11,51,41;}\n:root[data-paleta=\"lila\"]{--bg-1:#4a3a6b;--bg-2:#523f78;--bg-3:#66528f;--bg-4:#7a67a3;--fab-hi:#9a7fd1;--fab-mid:#7a5fb3;--fab-lo:#573f8a;--fab-glow:#c3aef0;--sparkle:#efe6ff;--ink:#4b3577;--ink-dark:#34235a;--btn:#7a62ad;--play:#9c86c9;--paper:#f2eff9;--paper-2:#e6e0f3;--paper-hi:#faf8fd;--m-hi:#f4f6f9;--m-mid:#cbd0d7;--m-lo:#9aa3b0;--m-dark:#7d8796;--m-text:#4a5566;--sh:52,35,90;}\n:root[data-paleta=\"vino\"]{--bg-1:#4a1020;--bg-2:#561327;--bg-3:#6e1c33;--bg-4:#842a42;--fab-hi:#9c2342;--fab-mid:#7a1832;--fab-lo:#560f22;--fab-glow:#c9506c;--sparkle:#ffd9e2;--ink:#5e1426;--ink-dark:#430c1b;--btn:#8a2440;--play:#b0566c;--paper:#f8eff1;--paper-2:#efdfe3;--paper-hi:#fdf8f9;--m-hi:#fbf3dc;--m-mid:#e2c98a;--m-lo:#b8923f;--m-dark:#8c6a26;--m-text:#5e4614;--sh:67,12,27;}\n:root[data-paleta=\"celeste\"]{--bg-1:#3a76a3;--bg-2:#4483b2;--bg-3:#5896c3;--bg-4:#70aad3;--fab-hi:#7cc0ea;--fab-mid:#4f9ed3;--fab-lo:#2f78ad;--fab-glow:#b4e0fb;--sparkle:#f0faff;--ink:#23577f;--ink-dark:#173f5f;--btn:#3a80b2;--play:#6aa9d4;--paper:#eef6fb;--paper-2:#ddebf5;--paper-hi:#f8fcfe;--m-hi:#f4f6f9;--m-mid:#cbd0d7;--m-lo:#9aa3b0;--m-dark:#7d8796;--m-text:#4a5566;--sh:23,63,95;}\n:root[data-paleta=\"negro\"]{--bg-1:#111111;--bg-2:#171717;--bg-3:#232323;--bg-4:#303030;--fab-hi:#3a3a3a;--fab-mid:#222222;--fab-lo:#0d0d0d;--fab-glow:#6b6b6b;--sparkle:#f0e0b0;--ink:#2a2a2a;--ink-dark:#111111;--btn:#1f1f1f;--play:#b8923f;--paper:#f7f4ee;--paper-2:#ece6da;--paper-hi:#fcfaf6;--m-hi:#fbf3dc;--m-mid:#e2c98a;--m-lo:#b8923f;--m-dark:#8c6a26;--m-text:#5e4614;--sh:0,0,0;}\n:root[data-paleta=\"champagne\"]{--bg-1:#7d6a4c;--bg-2:#8a7656;--bg-3:#9e8a66;--bg-4:#b39f7c;--fab-hi:#ead9b4;--fab-mid:#cdb486;--fab-lo:#a88c5c;--fab-glow:#f6ead0;--sparkle:#fffaf0;--ink:#6b5434;--ink-dark:#4d3a20;--btn:#9c7a45;--play:#c4a46c;--paper:#faf6ee;--paper-2:#f0e8d8;--paper-hi:#fdfbf6;--m-hi:#fbf3dc;--m-mid:#e2c98a;--m-lo:#b8923f;--m-dark:#8c6a26;--m-text:#5e4614;--sh:77,58,32;}\n/* Tipos de letra (data-letra en <html>) */\n:root[data-letra=\"romantica\"]{--f-script:\"Great Vibes\",\"Pinyon Script\",cursive;--f-caps:\"Cinzel\",Georgia,serif;--f-body:\"Cormorant Garamond\",Georgia,serif}\n:root[data-letra=\"caligrafia\"]{--f-script:\"Parisienne\",\"Pinyon Script\",cursive;--f-caps:\"Marcellus SC\",\"Marcellus\",Georgia,serif;--f-body:\"Marcellus\",Georgia,serif}\n:root[data-letra=\"moderna\"]{--f-script:\"Sacramento\",\"Great Vibes\",cursive;--f-caps:\"Josefin Sans\",system-ui,sans-serif;--f-body:\"Josefin Sans\",system-ui,sans-serif}\n:root[data-letra=\"clasica\"]{--f-script:\"Imperial Script\",\"Pinyon Script\",cursive;--f-caps:\"Playfair Display SC\",\"Playfair Display\",Georgia,serif;--f-body:\"Playfair Display\",Georgia,serif}\n:root[data-letra=\"infantil\"]{--f-script:\"Dancing Script\",cursive;--f-caps:\"Quicksand\",system-ui,sans-serif;--f-body:\"Quicksand\",system-ui,sans-serif}\n:root[data-letra=\"infantil\"] .script,:root[data-letra=\"infantil\"] .msg em,:root[data-letra=\"moderna\"] .msg em{font-weight:600}\nbody{background:var(--bg-1);color:var(--ink);font-family:var(--f-body);}\n.stage{\n  min-height:100%;\n  padding-block:24px 40px;\n  padding-left:max(10px, env(safe-area-inset-left,0px));\n  padding-right:max(10px, env(safe-area-inset-right,0px));\n  background:\n    radial-gradient(120% 60% at 10% 10%, var(--bg-4) 0%, transparent 55%),\n    radial-gradient(90% 50% at 90% 40%, var(--bg-3) 0%, transparent 60%),\n    radial-gradient(100% 60% at 20% 85%, var(--bg-3) 0%, transparent 60%),\n    linear-gradient(180deg,var(--bg-2),var(--bg-1) 50%,var(--bg-2));\n}\n.card{position:relative;max-width:440px;margin:0 auto;}\n.card > svg.edge{position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none;}\n.content{position:relative;z-index:1;padding:28px 40px 44px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:0;}\n@media (max-width:380px){.content{padding-inline:30px}}\n\nsection{width:100%;display:flex;flex-direction:column;align-items:center;gap:10px;padding-block:22px;}\n.sep{width:70%;height:1px;background:linear-gradient(90deg,transparent,var(--silver),transparent);margin-block:4px;}\n\n/* Portada */\n.hero-art{width:min(250px,80%);aspect-ratio:3/4;max-width:100%;}\n.hero-art svg{width:100%;height:100%;display:block;}\n.script{font-family:var(--f-script);font-weight:400;color:var(--ink-dark);line-height:1.1;}\n.caps{font-family:var(--f-caps);font-variant-caps:small-caps;letter-spacing:.06em;color:var(--ink);}\n.lead{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:1.02rem;line-height:1.35;color:var(--ink);letter-spacing:.04em;}\n.xv-name{font-size:clamp(3rem,13vw,4rem);margin-top:4px}\n.parents{font-size:2rem;}\n.parents span{display:block;font-size:1.6rem}\n\n/* Reproductor */\n.player-title{font-size:2rem;}\n.player{display:flex;align-items:center;justify-content:center;gap:22px;}\n.player button{background:none;border:0;color:var(--play);cursor:pointer;padding:4px;display:grid;place-items:center;border-radius:50%;}\n.player button:focus-visible{outline:2px solid var(--btn);outline-offset:3px}\n.player .ctl svg{width:24px;height:24px}\n.player .ctl.on{color:var(--ink-dark)}\n.player .play{width:62px;height:62px;color:#fff;\n  background:radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--play),white 28%),var(--play) 55%,color-mix(in srgb,var(--play),black 25%));\n  box-shadow:0 6px 14px rgba(var(--sh),.35), inset 0 1px 2px rgba(255,255,255,.5);}\n.player .play svg{width:28px;height:28px}\n.player-note{font-size:.9rem;color:var(--ink);font-style:italic;min-height:1.2em}\n\n/* Fecha */\n.date{display:flex;align-items:center;gap:12px;}\n.date .side{font-family:var(--f-script);font-size:1.9rem;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);padding:0 10px;line-height:1.3}\n.date .day{font-family:var(--f-script);font-size:3.6rem;line-height:1;color:var(--ink-dark)}\n.time{font-family:var(--f-script);font-size:1.9rem}\n\n/* Cuenta regresiva */\n.count{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;width:100%;}\n.count div{display:flex;flex-direction:column;align-items:center;gap:4px}\n.count b{font-family:var(--f-body);font-weight:500;font-size:2.2rem;color:var(--ink-dark);font-variant-numeric:tabular-nums;line-height:1}\n.count small{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:.8rem;letter-spacing:.08em}\n\n/* Polaroids */\n.polas{position:relative;height:180px;width:100%;}\n.pola{position:absolute;top:10px;width:38%;background:var(--paper-hi);padding:7px 7px 22px;box-shadow:0 8px 16px rgba(var(--sh),.28);}\n.pola .ph{aspect-ratio:1;background:linear-gradient(135deg,var(--paper-2),color-mix(in srgb,var(--paper-2),var(--play) 30%));display:grid;place-items:center;color:var(--ink);font-family:var(--f-caps);font-variant-caps:small-caps;font-size:.85rem;text-align:center;padding:6px}\n.pola:nth-child(1){left:0;transform:rotate(-8deg)}\n.pola:nth-child(3){right:0;transform:rotate(8deg)}\n.pola:nth-child(2){left:30%;width:40%;top:0;z-index:2}\n\n.ico{width:74px;height:74px;color:var(--ink)}\n.h-script{font-size:2.6rem}\n.place{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:1.25rem;line-height:1.3;letter-spacing:.04em}\n.btn{display:inline-block;background:var(--btn);color:#fff;text-decoration:none;font-family:var(--f-caps);font-variant-caps:small-caps;font-size:1.15rem;letter-spacing:.08em;padding:10px 26px;border-radius:14px;box-shadow:0 4px 10px rgba(var(--sh),.3);border:0;cursor:pointer}\n.full-name{font-size:clamp(2rem,9vw,2.5rem);margin-top:6px;text-wrap:balance}\n.venue{margin-top:6px;font-size:1.35rem;font-weight:600}\n.nav-btns{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}\n.btn:hover{background:var(--bg-3)}\n.btn:focus-visible{outline:2px solid var(--ink-dark);outline-offset:3px}\n\n/* Itinerario */\n.itin{list-style:none;margin:6px 0 0;padding:0;width:100%;position:relative;display:flex;flex-direction:column;gap:14px}\n.itin::before{content:\"\";position:absolute;left:50%;top:4px;bottom:4px;width:1px;background:var(--ink)}\n.itin li{display:grid;grid-template-columns:1fr 18px 1fr;align-items:center;gap:8px}\n.itin li::after{content:\"\";grid-column:2;grid-row:1;width:9px;height:9px;border-radius:50%;background:var(--btn);justify-self:center;box-shadow:0 0 0 3px var(--paper)}\n.itin .t{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:1rem;text-align:right;grid-column:1;grid-row:1}\n.itin .w{font-family:var(--f-script);font-size:1.6rem;text-align:left;grid-column:3;grid-row:1;color:var(--ink-dark)}\n.itin li:nth-child(even) .t{grid-column:3;text-align:left}\n.itin li:nth-child(even) .w{grid-column:1;text-align:right}\n\n.dress{font-family:var(--f-caps);font-variant-caps:small-caps;font-weight:600;font-size:1.05rem;letter-spacing:.1em}\n.small{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:1rem;line-height:1.4;color:var(--ink);letter-spacing:.03em}\n.env{width:84px;height:84px;border-radius:50%;background:var(--paper-2);border:1px solid var(--silver);display:grid;place-items:center;box-shadow:0 0 0 6px rgba(255,255,255,.5)}\n.env svg{width:44px;height:44px;color:var(--ink-dark)}\n.flour{width:120px;height:14px;color:var(--play)}\n.example{font-family:var(--f-body);font-style:italic;font-size:.85rem;color:var(--silver);text-align:center;margin:18px auto 0;max-width:440px}\n@media (prefers-reduced-motion:no-preference){\n  .player .play.playing{animation:pulse 1.6s ease-in-out infinite}\n  @keyframes pulse{50%{box-shadow:0 6px 14px rgba(var(--sh),.35),0 0 0 8px color-mix(in srgb,var(--play) 18%,transparent)}}\n}\n\n\n/* Foto de portada */\n.hero-photo{width:min(270px,82%);aspect-ratio:3/4;max-width:100%;border-radius:140px 140px 10px 10px;overflow:hidden;\n  padding:5px;background:linear-gradient(160deg,var(--m-hi),var(--m-lo) 30%,var(--m-hi) 55%,var(--m-lo) 80%,var(--m-hi));\n  box-shadow:0 14px 28px rgba(var(--sh),.35)}\n.hero-photo img{width:100%;height:100%;object-fit:cover;object-position:50% 25%;border-radius:135px 135px 6px 6px;display:block}\n.pola img{display:block;width:100%;aspect-ratio:1;object-fit:cover}\n/* Mensaje de Isabella */\n.msg-sec{padding-block:30px}\n.msg{position:relative;width:calc(100% + 20px);margin-inline:-10px;padding:34px 22px 30px;border-radius:4px;\n  background:linear-gradient(180deg,var(--paper-hi),var(--paper));\n  box-shadow:0 14px 30px rgba(var(--sh),.18), inset 0 0 0 1px var(--silver), inset 0 0 0 6px var(--paper-hi), inset 0 0 0 7px var(--silver);\n  display:flex;flex-direction:column;align-items:center;gap:16px}\n.msg p{margin:0;font-family:var(--f-caps);font-variant-caps:small-caps;font-size:1.02rem;line-height:1.55;letter-spacing:.05em;color:var(--ink);text-wrap:balance}\n.msg em{font-family:var(--f-script);font-variant-caps:normal;font-style:normal;font-size:1.75em;letter-spacing:0;color:var(--ink-dark);line-height:1;vertical-align:-.12em;padding-inline:2px}\n.msg em.big{font-size:2.1em;display:inline-block;margin-block:6px 2px}\n.m-div{display:flex;align-items:center;gap:10px;color:var(--btn);width:65%}\n.m-div span{flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--play))}\n.m-div span:last-child{background:linear-gradient(90deg,var(--play),transparent)}\n.m-div svg{width:13px;height:13px}\n.m-sign{font-size:3.6rem;margin-top:-10px}\n\n/* Fotos */\n.hero-photo{position:relative}\n.ph-empty{width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;\n  background:linear-gradient(160deg,var(--paper-hi),var(--paper-2));color:var(--ink);font-family:var(--f-caps);font-variant-caps:small-caps;letter-spacing:.06em;font-size:1rem;line-height:1.3;padding:16px}\n.hero-photo .ph-empty{border-radius:135px 135px 6px 6px}\n.ph-empty svg{width:46%;height:auto;opacity:.5}\n.hero-photo .ph-empty{justify-content:center;gap:12px;padding:24px 16px 26px}\n.hero-photo .ph-empty svg.doll{width:68%;opacity:1}\n.hero-photo .ph-empty span{background:rgba(var(--sh),.55);color:#fff;padding:4px 12px;border-radius:20px;font-size:.95rem}\n.ph-empty small{font-size:.8rem;opacity:.75}\n.gal{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;width:100%;padding:6px 4px 14px;scrollbar-width:thin}\n.gal figure{margin:0;flex:0 0 72%;scroll-snap-align:center;aspect-ratio:4/5;padding:5px;border-radius:6px;\n  background:linear-gradient(160deg,var(--m-hi),var(--m-lo) 30%,var(--m-hi) 55%,var(--m-lo) 80%,var(--m-hi));box-shadow:0 10px 20px rgba(var(--sh),.28)}\n.gal img,.gal .ph-empty{width:100%;height:100%;object-fit:cover;display:flex;border-radius:3px}\n.gal-hint{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:.85rem;letter-spacing:.12em;color:var(--ink);opacity:.8}\n\n\n/* Portada completa */\n.hero-photo.full{width:calc(100% + 56px);max-width:none;margin:-16px -28px 0;aspect-ratio:4/5;border-radius:0;padding:0;background:none;box-shadow:none;\n  -webkit-mask-image:linear-gradient(180deg,#000 78%,transparent);mask-image:linear-gradient(180deg,#000 78%,transparent)}\n.hero-photo.full img,.hero-photo.full .ph-empty{border-radius:0}\n.hero-photo.full .ph-empty{justify-content:flex-start;padding:22px 16px 60px}\n.hero-photo.full .ph-empty svg.doll{width:62%}\n.hero-photo.full + .xv-name{margin-top:-46px!important;position:relative}\n/* Sección libre */\n.libre{display:flex;flex-direction:column;align-items:center;gap:10px;width:100%}\n.libre + .libre{margin-top:18px}\n/* Confirmación con contactos */\n.rsvp{display:grid;grid-template-columns:repeat(auto-fit,minmax(76px,1fr));gap:8px;width:100%}\n.who{display:flex;flex-direction:column;align-items:center;gap:5px;padding:10px 2px;min-width:0;border-radius:10px;background:var(--paper-hi);\n  box-shadow:inset 0 0 0 1px var(--m-mid),0 6px 14px rgba(var(--sh),.12);text-decoration:none;color:var(--ink)}\n.who svg{width:50px;height:50px}\n.who b{font-family:var(--f-script);font-weight:400;font-size:1.45rem;line-height:1;color:var(--ink-dark)}\n.who span{font-family:var(--f-caps);font-variant-caps:small-caps;font-size:.85rem;letter-spacing:.08em}\n.who small{font-size:.8rem;font-variant-numeric:tabular-nums;opacity:.85}\n.who em{font-style:normal;font-family:var(--f-caps);font-variant-caps:small-caps;font-size:.8rem;letter-spacing:.06em;background:var(--btn);color:#fff;padding:3px 10px;border-radius:10px}\n.who:hover em{background:var(--bg-3)}\n.who:focus-visible{outline:2px solid var(--ink-dark);outline-offset:2px}\n\n/* Sobre de entrada */\nbody.locked{overflow:hidden}\n.intro{position:fixed;inset:0;z-index:50;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;\n  padding:calc(24px + env(safe-area-inset-top,0px)) max(16px, env(safe-area-inset-right,0px)) calc(24px + env(safe-area-inset-bottom,0px)) max(16px, env(safe-area-inset-left,0px));\n  text-align:center;color:var(--paper);\n  background:\n    radial-gradient(80% 50% at 15% 15%, var(--bg-4) 0%, transparent 60%),\n    radial-gradient(70% 45% at 85% 80%, var(--bg-3) 0%, transparent 60%),\n    linear-gradient(180deg,var(--bg-2),var(--bg-1));\n  transition:opacity .9s ease, visibility .9s;}\n.intro.gone{opacity:0;visibility:hidden}\n.intro .i-name{font-family:var(--f-script);font-size:clamp(3rem,14vw,4.4rem);line-height:1;color:#f4f6f9;text-shadow:0 2px 12px rgba(0,0,0,.25)}\n.intro .i-sub{font-family:var(--f-script);font-size:2rem;color:var(--silver);margin-top:-8px}\n.intro .i-date{font-family:var(--f-caps);font-variant-caps:small-caps;letter-spacing:.25em;font-size:.95rem;color:var(--silver)}\n.env-btn{background:none;border:0;padding:0;cursor:pointer;perspective:900px;margin-top:10px}\n.env-btn:focus-visible{outline:2px solid var(--silver);outline-offset:8px;border-radius:6px}\n.envelope{position:relative;width:min(290px,78vw);aspect-ratio:3/2;}\n.envelope .back,.envelope .front,.envelope .flap,.envelope .letter{position:absolute;left:0;width:100%}\n.envelope .back{inset:0;background:var(--fab-lo);border-radius:6px;box-shadow:0 18px 34px rgba(0,0,0,.4)}\n.envelope .letter{left:6%;width:88%;top:8%;height:84%;background:linear-gradient(160deg,var(--paper-hi),var(--paper-2));border-radius:4px;\n  display:grid;place-items:center;font-family:var(--f-script);font-size:1.8rem;color:var(--ink-dark);transition:transform .9s cubic-bezier(.3,.7,.3,1) .45s;z-index:1}\n.envelope .front{inset:0;z-index:2;border-radius:6px;\n  background:\n    radial-gradient(circle at 20% 30%, color-mix(in srgb,var(--sparkle) 40%,transparent) 0 1px, transparent 1.5px) 0 0/9px 9px,\n    linear-gradient(160deg,var(--fab-hi),var(--fab-mid) 55%,var(--fab-lo));\n  clip-path:polygon(0 0,50% 55%,100% 0,100% 100%,0 100%);}\n.envelope .flap{top:0;height:62%;z-index:3;transform-origin:top center;transition:transform .7s ease, z-index 0s .35s;\n  background:linear-gradient(180deg,color-mix(in srgb,var(--fab-hi),var(--fab-mid)),var(--fab-mid));clip-path:polygon(0 0,100% 0,50% 100%);\n  filter:drop-shadow(0 3px 3px rgba(0,0,0,.3))}\n.seal{position:absolute;left:50%;top:62%;transform:translate(-50%,-50%);z-index:4;width:62px;height:62px;border-radius:50%;\n  background:radial-gradient(circle at 35% 30%,#ffffff,var(--m-mid) 45%,var(--m-dark) 100%);\n  box-shadow:0 3px 8px rgba(0,0,0,.35), inset 0 0 0 4px rgba(255,255,255,.35);\n  display:grid;place-items:center;font-family:var(--f-script);font-size:1.7rem;color:var(--m-text);transition:opacity .35s}\n.intro .hint{font-family:var(--f-caps);font-variant-caps:small-caps;letter-spacing:.2em;font-size:.9rem;color:var(--silver);display:flex;align-items:center;gap:10px}\n.intro .hint::before,.intro .hint::after{content:\"\";width:28px;height:1px;background:var(--silver)}\n.intro.open .flap{transform:rotateX(180deg);z-index:0}\n.intro.open .seal{opacity:0}\n.intro.open .letter{transform:translateY(-55%)}\n@media (prefers-reduced-motion:no-preference){\n  .intro:not(.open) .seal{animation:breathe 2.2s ease-in-out infinite}\n  @keyframes breathe{50%{transform:translate(-50%,-50%) scale(1.07)}}\n}\n\n<\/style>\n<\/head>\n<body>\n<div class=\"intro\" id=\"intro\" data-sec=\"sobre\">\n  <div class=\"i-name\" data-t=\"nombre\"><\/div>\n  <div class=\"i-sub\" data-t=\"subtitulo\"><\/div>\n  <div class=\"i-date\" id=\"iDate\"><\/div>\n  <button class=\"env-btn\" id=\"openEnv\" aria-label=\"Abrir invitación\">\n    <div class=\"envelope\">\n      <div class=\"back\"><\/div>\n      <div class=\"letter\">Bienvenidos<\/div>\n      <div class=\"front\"><\/div>\n      <div class=\"flap\"><\/div>\n      <div class=\"seal\" data-t=\"sello\"><\/div>\n    <\/div>\n  <\/button>\n  <div class=\"hint\">Toca el sobre para abrir<\/div>\n<\/div>\n\n<div class=\"stage\">\n  <div class=\"card\" id=\"card\">\n    <div class=\"content\">\n      <section style=\"padding-top:8px\">\n        <div class=\"hero-photo\" id=\"heroPhoto\"><\/div>\n        <div class=\"tiara\" aria-hidden=\"true\" style=\"margin-top:10px\"><\/div>\n        <h1 class=\"script xv-name\" style=\"margin:0\" data-t=\"nombre\"><\/h1>\n        <div class=\"caps\" style=\"font-size:1.1rem;letter-spacing:.3em\" data-t=\"subtitulo\"><\/div>\n      <\/section>\n\n      <section data-sec=\"musica\">\n        <div class=\"script player-title\">Dale play<\/div>\n        <div class=\"player\">\n          <button class=\"ctl\" id=\"shuf\" aria-label=\"Aleatorio\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 3h5v5M4 20 21 3M21 16v5h-5M15 15l6 6M4 4l5 5\"/><\/svg><\/button>\n          <button class=\"ctl\" id=\"prev\" aria-label=\"Anterior\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M6 5h2v14H6zM20 5v14L9 12z\"/><\/svg><\/button>\n          <button class=\"play\" id=\"play\" aria-label=\"Reproducir\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\" id=\"playIco\"><path d=\"M8 5v14l11-7z\"/><\/svg><\/button>\n          <button class=\"ctl\" id=\"next\" aria-label=\"Siguiente\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M16 5h2v14h-2zM4 5v14l11-7z\"/><\/svg><\/button>\n          <button class=\"ctl\" id=\"rep\" aria-label=\"Repetir\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m17 1 4 4-4 4\"/><path d=\"M3 11V9a4 4 0 0 1 4-4h14\"/><path d=\"m7 23-4-4 4-4\"/><path d=\"M21 13v2a4 4 0 0 1-4 4H3\"/><\/svg><\/button>\n        <\/div>\n        <div class=\"player-note\" id=\"note\"><\/div>\n        <audio id=\"audio\" preload=\"none\"><\/audio>\n      <\/section>\n\n      <section>\n        <p class=\"lead\" style=\"margin:0\" data-t=\"textoBendicion\"><\/p>\n        <div class=\"script parents\" id=\"parents\"><\/div>\n        <p class=\"lead\" style=\"margin:0\" data-t=\"textoInvitacion\"><\/p>\n        <div class=\"script full-name\" id=\"fullName\"><\/div>\n      <\/section>\n\n      <section>\n        <p class=\"lead\" style=\"margin:0\" data-t=\"textoFecha\"><\/p>\n        <div class=\"date\" id=\"dateBox\"><\/div>\n        <div class=\"time\" id=\"timeBig\"><\/div>\n        <div class=\"sep\"><\/div>\n        <div class=\"caps\" style=\"font-size:1rem;letter-spacing:.2em\">Faltan<\/div>\n        <div class=\"count\" aria-live=\"polite\">\n          <div><b id=\"cd\">0<\/b><small>Días<\/small><\/div>\n          <div><b id=\"ch\">00<\/b><small>Horas<\/small><\/div>\n          <div><b id=\"cm\">00<\/b><small>Minutos<\/small><\/div>\n          <div><b id=\"cs\">00<\/b><small>Segundos<\/small><\/div>\n        <\/div>\n      <\/section>\n\n      <section data-sec=\"recuerdos\">\n        <div class=\"polas\" id=\"polas\"><\/div>\n      <\/section>\n\n      <section data-sec=\"galeria\">\n        <h2 class=\"script h-script\" style=\"margin:0\" data-t=\"tituloGaleria\"><\/h2>\n        <div class=\"gal\" id=\"galeria\"><\/div>\n        <div class=\"gal-hint\">Desliza para ver más<\/div>\n      <\/section>\n\n      <section data-sec=\"ceremonia\">\n        <svg class=\"ico\" viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M40 6v14M34 12h12\"/><path d=\"M24 34l16-14 16 14\"/><path d=\"M28 32v36h24V32\"/><path d=\"M14 68V46l14-10M66 68V46L52 36\"/><path d=\"M10 68h60\"/><path d=\"M36 68V54a4 4 0 0 1 8 0v14\"/><circle cx=\"40\" cy=\"40\" r=\"4\"/>\n        <\/svg>\n        <h2 class=\"script h-script\" style=\"margin:0\" data-t=\"ceremonia.titulo\"><\/h2>\n        <div class=\"place\" id=\"cerHora\"><\/div>\n        <div id=\"cerNav\"><\/div>\n        <div class=\"place venue\" data-t=\"ceremonia.lugar\"><\/div>\n      <\/section>\n\n      <section data-sec=\"recepcion\">\n        <svg class=\"ico\" viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <path d=\"M18 10h16l-2 22c-1 8-11 8-12 0z\"/><path d=\"M26 40v26M18 68h16\"/><path d=\"M19 22h14\" opacity=\".5\"/>\n          <path d=\"M46 10h16l-2 22c-1 8-11 8-12 0z\"/><path d=\"M54 40v26M46 68h16\"/><path d=\"M47 22h14\" opacity=\".5\"/>\n        <\/svg>\n        <h2 class=\"script h-script\" style=\"margin:0\" data-t=\"recepcion.titulo\"><\/h2>\n        <div class=\"place\" id=\"recHora\"><\/div>\n        <div id=\"recNav\"><\/div>\n        <div class=\"place venue\" data-t=\"recepcion.lugar\"><\/div>\n      <\/section>\n\n      <section data-sec=\"itinerario\">\n        <h2 class=\"script h-script\" style=\"margin:0\">Itinerario<\/h2>\n        <ul class=\"itin\" id=\"itin\"><\/ul>\n      <\/section>\n\n      <section data-sec=\"tradiciones\">\n        <h2 class=\"script h-script\" style=\"margin:0\">Momentos especiales<\/h2>\n        <ul class=\"trads\" id=\"tradiciones\"><\/ul>\n      <\/section>\n\n      <section class=\"msg-sec\" data-sec=\"mensaje\">\n        <div class=\"msg\" id=\"msg\"><\/div>\n      <\/section>\n\n      <section data-sec=\"vestimenta\">\n        <h2 class=\"script h-script\" style=\"margin:0\">Código de vestimenta<\/h2>\n        <div class=\"dress\" data-t=\"vestimenta.tipo\"><\/div>\n        <svg viewBox=\"0 0 120 70\" width=\"120\" height=\"70\" aria-hidden=\"true\">\n          <path d=\"M14 8l10-4 6 10 6-10 10 4 6 54H8z\" style=\"fill:var(--ink-dark)\"/><path d=\"M24 4l6 18 6-18\" style=\"fill:var(--paper)\"/><path d=\"M27 12l3 3 3-3-3 3z\" style=\"fill:var(--ink-dark);stroke:var(--ink-dark)\" stroke-width=\"2\"/>\n          <path d=\"M80 4h12l2 10 4 10 14 40H66l14-40 4-10z\" style=\"fill:var(--ink-dark)\"/>\n        <\/svg>\n        <p class=\"small\" style=\"margin:0\" data-t=\"vestimenta.nota\"><\/p>\n      <\/section>\n\n      <section data-sec=\"sobres\">\n        <h2 class=\"script h-script\" style=\"margin:0\" data-t=\"sobres.titulo\"><\/h2>\n        <p class=\"small\" style=\"margin:0\" data-t=\"sobres.texto1\"><\/p>\n        <div class=\"env\"><svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><rect x=\"6\" y=\"12\" width=\"36\" height=\"26\" rx=\"2\" style=\"fill:var(--paper)\"/><path d=\"M6 14l18 13 18-13\"/><path d=\"M24 20c-2-3-6-1-4 2l4 3 4-3c2-3-2-5-4-2z\" fill=\"currentColor\"/><\/svg><\/div>\n        <svg class=\"flour\" viewBox=\"0 0 120 14\" aria-hidden=\"true\"><path d=\"M2 7h44M74 7h44\" stroke=\"currentColor\"/><path d=\"M60 2c-6 0-6 10 0 10s6-10 0-10zM52 7c-3-4-8-4-8 0s5 4 8 0zM68 7c3-4 8-4 8 0s-5 4-8 0z\" fill=\"none\" stroke=\"currentColor\"/><\/svg>\n        <p class=\"small\" style=\"margin:0\" data-t=\"sobres.texto2\"><\/p>\n      <\/section>\n\n      <section data-sec=\"libres\" id=\"libres\"><\/section>\n\n      <section data-sec=\"confirmacion\">\n        <h2 class=\"script\" style=\"margin:0;font-size:2.7rem\">Confirma asistencia<\/h2>\n        <p class=\"small\" style=\"margin:0\">Elige con quién confirmar por WhatsApp<\/p>\n        <div class=\"rsvp\" id=\"rsvp\"><\/div>\n        <p class=\"small\" style=\"margin:0\" data-t=\"agradecimiento\"><\/p>\n      <\/section>\n    <\/div>\n  <\/div>\n<\/div>\n\n<script>\n(function(){\n  const C=window.CFG, $=id=>document.getElementById(id);\n  const esc=t=>String(t??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const get=(o,p)=>p.split('.').reduce((a,k)=>a==null?a:a[k],o);\n  const MESES=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];\n  const h12=h=>{if(!h)return'';let[H,M]=h.split(':').map(Number);const ap=H>=12?'p.m.':'a.m.';H=H%12||12;return H+':'+String(M).padStart(2,'0')+' '+ap;};\n  const SIL={'mama': '<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><circle cx=\"32\" cy=\"32\" r=\"31\" style=\"fill:var(--paper-2)\"/><path d=\"M18 34c0-14 6-22 14-22s14 8 14 22c0 6-2 10-2 10H20s-2-4-2-10z\" style=\"fill:var(--ink)\" opacity=\".85\"/><circle cx=\"32\" cy=\"27\" r=\"9\" style=\"fill:var(--paper-hi)\"/><path d=\"M14 60c2-10 9-15 18-15s16 5 18 15\" style=\"fill:var(--ink)\"/><\/svg>', 'papa': '<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><circle cx=\"32\" cy=\"32\" r=\"31\" style=\"fill:var(--paper-2)\"/><path d=\"M22 24c0-8 5-12 10-12s10 4 10 12l-1 2H23z\" style=\"fill:var(--ink)\"/><circle cx=\"32\" cy=\"27\" r=\"9\" style=\"fill:var(--paper-hi)\"/><path d=\"M12 60c2-10 10-16 20-16s18 6 20 16\" style=\"fill:var(--ink)\"/><path d=\"M30 45h4l1 4-3 9-3-9z\" style=\"fill:var(--paper-hi)\"/><\/svg>', 'quince': '<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><circle cx=\"32\" cy=\"32\" r=\"31\" style=\"fill:var(--paper-2)\"/><path d=\"M19 36c0-14 5-22 13-22s13 8 13 22c0 8-3 14-3 14H22s-3-6-3-14z\" style=\"fill:var(--ink)\" opacity=\".85\"/><circle cx=\"32\" cy=\"28\" r=\"8.5\" style=\"fill:var(--paper-hi)\"/><path d=\"M25 16l3 3 4-5 4 5 3-3-1 5H26z\" style=\"fill:var(--m-lo)\"/><path d=\"M16 60c2-9 8-14 16-14s14 5 16 14\" style=\"fill:var(--ink)\"/><\/svg>'};\n  const DRESS='<svg class=\"doll\" viewBox=\"0 0 240 320\" aria-hidden=\"true\"><defs><linearGradient id=\"gown\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" style=\"stop-color:var(--fab-hi)\"/><stop offset=\".55\" style=\"stop-color:var(--fab-mid)\"/><stop offset=\"1\" style=\"stop-color:var(--fab-lo)\"/><\/linearGradient><radialGradient id=\"tulle\" cx=\".5\" cy=\".2\" r=\".9\"><stop offset=\"0\" style=\"stop-color:var(--fab-glow)\" stop-opacity=\".55\"/><stop offset=\"1\" style=\"stop-color:var(--bg-1)\" stop-opacity=\"0\"/><\/radialGradient><pattern id=\"spark\" width=\"9\" height=\"9\" patternUnits=\"userSpaceOnUse\"><circle cx=\"2\" cy=\"3\" r=\".7\" style=\"fill:var(--sparkle)\" opacity=\".7\"/><circle cx=\"7\" cy=\"7\" r=\".5\" fill=\"#ffffff\" opacity=\".6\"/><\/pattern><\/defs><ellipse cx=\"120\" cy=\"306\" rx=\"104\" ry=\"10\" style=\"fill:var(--bg-1)\" opacity=\".18\"/><path d=\"M104 22c0-14 32-14 32 0 8 10 8 28 2 40-6 6-30 6-36 0-6-12-6-30 2-40z\" fill=\"#5a3a2e\"/><circle cx=\"120\" cy=\"14\" r=\"5\" style=\"fill:var(--m-mid)\"/><path d=\"M104 58c4 4 28 4 32 0l6 20c-14 4-30 4-44 0z\" fill=\"#e2b9a2\"/><path d=\"M98 78c14 5 30 5 44 0l-4 50c-12 4-24 4-36 0z\" fill=\"url(#gown)\"/><path d=\"M120 128c-16-14-32-10-30 4s20 8 30-4c10 12 28 18 30 4s-14-18-30-4z\" style=\"fill:var(--fab-mid)\"/><path d=\"M120 128l-8 30M120 128l8 30\" style=\"stroke:var(--fab-mid)\" stroke-width=\"7\" stroke-linecap=\"round\"/><circle cx=\"120\" cy=\"128\" r=\"5\" style=\"fill:var(--fab-hi)\"/><path id=\"skirt\" d=\"M102 126c-30 60-70 120-84 176 30 12 174 12 204 0-14-56-54-116-84-176-12 4-24 4-36 0z\" fill=\"url(#gown)\"/><use href=\"#skirt\" fill=\"url(#spark)\"/><use href=\"#skirt\" fill=\"url(#tulle)\"/><path d=\"M110 140c-10 50-30 110-48 162M130 140c10 50 30 110 48 162M120 140v166\" style=\"stroke:var(--fab-lo)\" stroke-width=\"1\" opacity=\".35\" fill=\"none\"/><\/svg>';\n  const empty=(txt,sub,ico)=>`<div class=\"ph-empty\">${ico||''}<span>${txt}<\/span>${sub?`<small>${sub}<\/small>`:''}<\/div>`;\n  const nav=(w,m)=>(w||m)?`<div class=\"caps\" style=\"font-size:.95rem;letter-spacing:.2em;margin-bottom:10px\">Cómo llegar<\/div><div class=\"nav-btns\">${w?`<a class=\"btn\" href=\"${esc(w)}\" target=\"_blank\" rel=\"noopener\">Waze<\/a>`:''}${m?`<a class=\"btn\" href=\"${esc(m)}\" target=\"_blank\" rel=\"noopener\">Google Maps<\/a>`:''}<\/div>`:'';\n\n  // Secciones\n  document.querySelectorAll('[data-sec]').forEach(el=>{ if(C.secciones&&C.secciones[el.dataset.sec]===false) el.hidden=true; });\n  // Textos simples\n  document.querySelectorAll('[data-t]').forEach(el=>{ el.textContent=get(C,el.dataset.t)||''; });\n  // Papás y nombre completo\n  $('parents').innerHTML=[C.papa,C.mama].filter(Boolean).map(esc).join('<span>y<\/span>');\n  const nc=String(C.nombreCompleto||'').trim().split(/\\s+/);\n  $('fullName').innerHTML=nc.length>3?esc(nc.slice(0,Math.ceil(nc.length/2)).join(' '))+'<br>'+esc(nc.slice(Math.ceil(nc.length/2)).join(' ')):esc(C.nombreCompleto||'');\n  // Fecha\n  const [Y,Mo,D]=(C.fecha||'2027-01-01').split('-').map(Number);\n  $('dateBox').innerHTML=`<span class=\"side\">${MESES[Mo-1]}<\/span><span class=\"day\">${D}<\/span><span class=\"side\">${Y}<\/span>`;\n  $('timeBig').textContent=(C.hora||'')+' hrs';\n  $('iDate').textContent=`${D} · ${MESES[Mo-1]} · ${Y}`;\n  // Lugares\n  $('cerHora').textContent=h12(C.ceremonia.hora); $('cerNav').innerHTML=nav(C.ceremonia.waze,C.ceremonia.maps);\n  $('recHora').textContent=h12(C.recepcion.hora); $('recNav').innerHTML=nav(C.recepcion.waze,C.recepcion.maps);\n  // Itinerario\n  $('itin').innerHTML=(C.itinerario||[]).map(x=>`<li><span class=\"t\">${esc(h12(x.hora).replace(' p.m.',' PM').replace(' a.m.',' AM'))}<\/span><span class=\"w\">${esc(x.actividad)}<\/span><\/li>`).join('');\n  // Mensaje\n  const MD='<div class=\"m-div\" aria-hidden=\"true\"><span><\/span><svg viewBox=\"0 0 24 24\"><path d=\"M12 21s-7-4.4-9.3-9C1 8.4 3.2 5 6.5 5c2 0 3.6 1.2 5.5 3.3C13.9 6.2 15.5 5 17.5 5 20.8 5 23 8.4 21.3 12 19 16.6 12 21 12 21z\" fill=\"currentColor\"/><\/svg><span><\/span><\/div>';\n  const fmt=t=>esc(t).replace(/\\*(.+?)\\*/g,'<em>$1<\/em>').replace(/\\n/g,'<br>');\n  const ps=(C.mensaje.parrafos||[]).filter(p=>p.trim());\n  $('msg').innerHTML=ps.map(p=>`<p>${fmt(p)}<\/p>`).join(MD)+(C.mensaje.despedida||C.mensaje.firma?MD+`<p>${esc(C.mensaje.despedida)}<\/p><div class=\"script m-sign\">${esc(C.mensaje.firma)}<\/div>`:'');\n  const first=$('msg').querySelector('p em'); if(first) first.classList.add('big');\n  // Secciones libres\n  const L=(C.libres||[]).filter(x=>x.titulo||x.texto);\n  $('libres').innerHTML=L.map(x=>`<div class=\"libre\"><h2 class=\"script h-script\" style=\"margin:0\">${esc(x.titulo)}<\/h2><p class=\"small\" style=\"margin:0\">${fmt(x.texto)}<\/p><\/div>`).join('');\n  if(!L.length) $('libres').hidden=true;\n  // Confirmación\n  const ft=t=>t.replace(/\\D/g,'').replace(/^(\\d{4})(\\d{4})$/,'$1-$2');\n  $('rsvp').innerHTML=(C.contactos||[]).filter(c=>c.tel).map(c=>`<a class=\"who\" href=\"https://wa.me/502${c.tel.replace(/\\D/g,'')}?text=${encodeURIComponent(C.mensajeWA||'')}\" target=\"_blank\" rel=\"noopener\">${SIL[c.rol]||SIL.mama}<span>${esc(c.titulo)}<\/span><b>${esc(c.nombre)}<\/b><small>${ft(c.tel)}<\/small><em>WhatsApp<\/em><\/a>`).join('');\n  // Fotos\n  const F=C.fotos||{};\n  const hp=$('heroPhoto'); if(C.portada==='completa') hp.classList.add('full');\n  hp.innerHTML=F.portada?`<img src=\"${F.portada}\" alt=\"Foto principal\">`:empty('Foto con vestido','',DRESS);\n  $('polas').innerHTML=(F.recuerdos||['','','']).slice(0,3).map((src,i)=>`<div class=\"pola\">${src?`<img src=\"${src}\" alt=\"Recuerdo ${i+1}\">`:`<div class=\"ph\" style=\"${i===0?'padding-right:30%':i===2?'padding-left:30%':''}\">Foto ${i+1}<\/div>`}<\/div>`).join('');\n  const G=F.galeria||[];\n  if(!G.length) document.querySelector('[data-sec=\"galeria\"]').hidden=true;\n  else $('galeria').innerHTML=G.map((src,i)=>`<figure>${src?`<img src=\"${src}\" alt=\"Foto ${i+4}\">`:empty('Foto extra '+(i+1),'Servicio adicional')}<\/figure>`).join('');\n  // Música\n  if(C.cancion) $('audio').src=C.cancion;\n\n  // Bordes rasgados plateados sobre acuarela azul marino\n  const card=document.getElementById('card');\n  function rnd(seed){return function(){seed=(seed*16807)%2147483647;return (seed-1)/2147483646;}}\n  function edgePath(w,h,inset,amp,seed){\n    const r=rnd(seed); const step=10; let pts=[];\n    for(let y=0;y<=h;y+=step) pts.push([inset+r()*amp,y]);\n    let rightPts=[]; for(let y=h;y>=0;y-=step) rightPts.push([w-inset-r()*amp,y]);\n    return 'M'+[...pts,...rightPts].map(p=>p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' L')+' Z';\n  }\n  function draw(){\n    const w=card.clientWidth,h=card.clientHeight;\n    const old=card.querySelector('svg.edge'); if(old) old.remove();\n    const ns='http://www.w3.org/2000/svg';\n    const svg=document.createElementNS(ns,'svg'); svg.setAttribute('class','edge');\n    svg.setAttribute('viewBox',`0 0 ${w} ${h}`); svg.setAttribute('preserveAspectRatio','none');\n    svg.innerHTML=`<defs>\n      <linearGradient id=\"sil\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n        <stop offset=\"0\" style=\"stop-color:var(--m-hi)\"/><stop offset=\".2\" style=\"stop-color:var(--m-lo)\"/><stop offset=\".4\" style=\"stop-color:var(--m-hi)\"/><stop offset=\".6\" style=\"stop-color:var(--m-lo)\"/><stop offset=\".8\" style=\"stop-color:var(--m-hi)\"/><stop offset=\"1\" style=\"stop-color:var(--m-mid)\"/>\n      <\/linearGradient>\n      <pattern id=\"gl\" width=\"6\" height=\"6\" patternUnits=\"userSpaceOnUse\"><circle cx=\"1.5\" cy=\"2\" r=\".8\" fill=\"#ffffff\"/><circle cx=\"4.5\" cy=\"4.5\" r=\".6\" style=\"fill:var(--m-dark)\"/><\/pattern>\n      <linearGradient id=\"pap\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n        <stop offset=\"0\" style=\"stop-color:var(--paper-hi)\"/><stop offset=\".5\" style=\"stop-color:var(--paper)\"/><stop offset=\"1\" style=\"stop-color:var(--paper-2)\"/>\n      <\/linearGradient>\n    <\/defs>\n    <path d=\"${edgePath(w,h,2,12,7)}\" fill=\"url(#sil)\"/>\n    <path d=\"${edgePath(w,h,2,12,7)}\" fill=\"url(#gl)\" opacity=\".7\"/>\n    <path d=\"${edgePath(w,h,10,12,19)}\" fill=\"url(#pap)\"/>`;\n    card.prepend(svg);\n  }\n  draw(); let t; addEventListener('resize',()=>{clearTimeout(t);t=setTimeout(draw,120)});\n  if(document.fonts) document.fonts.ready.then(draw);\n\n  // Cuenta regresiva\n  const target=new Date(`${C.fecha}T${C.hora||'00:00'}:00-06:00`).getTime();\n  const pad=n=>String(n).padStart(2,'0');\n  function tick(){\n    let s=Math.max(0,Math.floor((target-Date.now())/1000));\n    $('cd').textContent=Math.floor(s/86400); s%=86400;\n    $('ch').textContent=pad(Math.floor(s/3600)); s%=3600;\n    $('cm').textContent=pad(Math.floor(s/60)); $('cs').textContent=pad(s%60);\n  }\n  tick(); setInterval(tick,1000);\n\n  // Reproductor\n  const audio=document.getElementById('audio'), play=document.getElementById('play'), ico=document.getElementById('playIco'), note=document.getElementById('note');\n  const playP='<path d=\"M8 5v14l11-7z\"/>', pauseP='<path d=\"M7 5h4v14H7zM13 5h4v14h-4z\"/>';\n  let on=false;\n  function setState(v){on=v;ico.innerHTML=v?pauseP:playP;play.classList.toggle('playing',v);play.setAttribute('aria-label',v?'Pausar':'Reproducir');}\n  play.addEventListener('click',()=>{\n    if(!audio.getAttribute('src')){ setState(!on); note.textContent=on?'Aquí sonará la canción de la quinceañera':''; return; }\n    if(audio.paused){audio.play().then(()=>setState(true)).catch(()=>{});} else {audio.pause();setState(false);}\n  });\n  audio.addEventListener('ended',()=>{ if(!audio.loop) setState(false); });\n  ['shuf','rep'].forEach(id=>{const b=document.getElementById(id);b.addEventListener('click',()=>{const v=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',v);b.classList.toggle('on',v);if(id==='rep')audio.loop=v;});});\n  ['prev','next'].forEach(id=>document.getElementById(id).addEventListener('click',()=>{if(audio.getAttribute('src')){audio.currentTime=0;}}));\n\n  // Sobre\n  const intro=$('intro');\n  if(C._preview && !C._verSobre){ intro.hidden=true; }\n  else if(!C.secciones||C.secciones.sobre!==false){\n    document.body.classList.add('locked');\n    $('openEnv').addEventListener('click',()=>{\n      if(intro.classList.contains('open')) return;\n      intro.classList.add('open');\n      if(!on && $('audio').getAttribute('src')) play.click();\n      setTimeout(()=>{intro.classList.add('gone');document.body.classList.remove('locked');window.scrollTo(0,0);},1700);\n    });\n  }\n  if(C._scroll) requestAnimationFrame(()=>window.scrollTo(0,C._scroll));\n})();\n<\/script>\n<script id=\"ambient\">(function(){\n  /* Animación ambiental: CFG.animacion = \"ninguna\" | \"mariposas\" | \"petalos\" | \"destellos\" | \"luciernagas\" | \"corazones\" */\n  const C=window.CFG||{}, tipo=C.animacion||'ninguna';\n  if(tipo==='ninguna') return;\n  if(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;\n  const cv=document.createElement('canvas');\n  cv.setAttribute('aria-hidden','true');\n  cv.style.cssText='position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:30';\n  document.body.appendChild(cv);\n  const ctx=cv.getContext('2d');\n  let W=0,H=0,dpr=1;\n  function size(){dpr=Math.min(2,window.devicePixelRatio||1);W=cv.width=innerWidth*dpr;H=cv.height=innerHeight*dpr;}\n  size(); addEventListener('resize',size);\n  const cs=getComputedStyle(document.documentElement), v=n=>cs.getPropertyValue(n).trim();\n  const pal=[v('--fab-hi'),v('--fab-glow'),v('--fab-mid'),v('--sparkle')].filter(Boolean);\n  const metal=[v('--m-hi'),v('--m-mid'),v('--m-lo')].filter(Boolean);\n  const R=(a,b)=>a+Math.random()*(b-a), pick=a=>a[Math.floor(Math.random()*a.length)];\n  let P=[];\n  const N={mariposas:6,petalos:16,destellos:22,luciernagas:26,corazones:12}[tipo]||12;\n\n  function make(first){\n    const p={x:R(0,W),y:first?R(0,H):(tipo==='petalos'?-20*dpr:H+20*dpr),t:R(0,1000),c:pick(pal),s:R(.7,1.2)*dpr};\n    if(tipo==='mariposas'){p.y=R(0,H);p.vx=R(-.4,.4)*dpr;p.vy=R(-.3,.3)*dpr;p.c2=pick(pal.concat(metal));p.f=R(.18,.26);}\n    if(tipo==='petalos'){p.vy=R(.35,.8)*dpr;p.a=R(0,6);p.va=R(-.02,.02);p.amp=R(.4,1.2);}\n    if(tipo==='destellos'){p.y=R(0,H);p.life=0;p.max=R(80,180);p.c=pick(metal.concat(['#ffffff']));}\n    if(tipo==='luciernagas'){p.y=R(0,H);p.vx=R(-.25,.25)*dpr;p.vy=R(-.25,.25)*dpr;}\n    if(tipo==='corazones'){p.vy=-R(.3,.6)*dpr;p.amp=R(.3,.9);}\n    return p;\n  }\n  for(let i=0;i<N;i++) P.push(make(true));\n\n  function butterfly(p){\n    const flap=Math.abs(Math.sin(p.t*p.f)), s=12*p.s, ang=Math.atan2(p.vy,p.vx)+Math.PI/2;\n    ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(ang*.25);\n    for(const side of [-1,1]){\n      ctx.save(); ctx.scale(side*(.25+.75*flap),1);\n      ctx.globalAlpha=.85;\n      ctx.fillStyle=p.c; ctx.beginPath(); ctx.ellipse(s*.9,-s*.5,s,s*.75,-.5,0,Math.PI*2); ctx.fill();\n      ctx.fillStyle=p.c2; ctx.beginPath(); ctx.ellipse(s*.7,s*.55,s*.62,s*.5,.5,0,Math.PI*2); ctx.fill();\n      ctx.globalAlpha=.5; ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(s*.95,-s*.55,s*.22,0,Math.PI*2); ctx.fill();\n      ctx.restore();\n    }\n    ctx.globalAlpha=.9; ctx.fillStyle='#3a2e2a'; ctx.beginPath(); ctx.ellipse(0,0,s*.14,s*.85,0,0,Math.PI*2); ctx.fill();\n    ctx.strokeStyle='#3a2e2a'; ctx.lineWidth=dpr*.8; ctx.beginPath(); ctx.moveTo(0,-s*.8); ctx.lineTo(-s*.35,-s*1.4); ctx.moveTo(0,-s*.8); ctx.lineTo(s*.35,-s*1.4); ctx.stroke();\n    ctx.restore();\n  }\n  function heart(x,y,s){ctx.beginPath();ctx.moveTo(x,y+s*.3);ctx.bezierCurveTo(x,y,x-s*.5,y,x-s*.5,y+s*.3);ctx.bezierCurveTo(x-s*.5,y+s*.6,x,y+s*.8,x,y+s);ctx.bezierCurveTo(x,y+s*.8,x+s*.5,y+s*.6,x+s*.5,y+s*.3);ctx.bezierCurveTo(x+s*.5,y,x,y,x,y+s*.3);ctx.fill();}\n  function star(x,y,r){ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,rr=i%2?r*.28:r;ctx.lineTo(x+Math.cos(a)*rr,y+Math.sin(a)*rr);}ctx.closePath();ctx.fill();}\n\n  let last=0;\n  function frame(ts){\n    if(document.hidden){requestAnimationFrame(frame);return;}\n    if(ts-last<33){requestAnimationFrame(frame);return;} last=ts;\n    ctx.clearRect(0,0,W,H);\n    P.forEach((p,i)=>{\n      p.t+=1;\n      if(tipo==='mariposas'){\n        p.vx+=Math.sin(p.t*.013+i)*.012*dpr; p.vy+=Math.cos(p.t*.011+i*2)*.012*dpr;\n        const sp=Math.hypot(p.vx,p.vy), mx=.9*dpr; if(sp>mx){p.vx*=mx/sp;p.vy*=mx/sp;}\n        p.x+=p.vx; p.y+=p.vy+Math.sin(p.t*p.f)*.25*dpr;\n        if(p.x<-30*dpr)p.x=W+20*dpr; if(p.x>W+30*dpr)p.x=-20*dpr; if(p.y<-30*dpr)p.y=H+20*dpr; if(p.y>H+30*dpr)p.y=-20*dpr;\n        butterfly(p);\n      } else if(tipo==='petalos'){\n        p.y+=p.vy; p.x+=Math.sin(p.t*.02)*p.amp*dpr; p.a+=p.va;\n        ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.a); ctx.scale(1,Math.abs(Math.cos(p.t*.03))*.6+.4);\n        ctx.globalAlpha=.75; ctx.fillStyle=p.c; ctx.beginPath(); ctx.ellipse(0,0,7*p.s,4.5*p.s,0,0,Math.PI*2); ctx.fill(); ctx.restore();\n        if(p.y>H+20*dpr) P[i]=make(false);\n      } else if(tipo==='destellos'){\n        p.life++; const k=Math.sin(p.life/p.max*Math.PI);\n        ctx.globalAlpha=k*.9; ctx.fillStyle=p.c; star(p.x,p.y,6*p.s*k+1);\n        if(p.life>p.max) P[i]=make(true);\n      } else if(tipo==='luciernagas'){\n        p.vx+=R(-.03,.03)*dpr; p.vy+=R(-.03,.03)*dpr; p.vx*=.98; p.vy*=.98; p.x+=p.vx; p.y+=p.vy;\n        if(p.x<0||p.x>W)p.vx*=-1; if(p.y<0||p.y>H)p.vy*=-1;\n        const g=.45+.55*Math.abs(Math.sin(p.t*.03+i)), r=10*p.s;\n        const gr=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,r*2.4); gr.addColorStop(0,`rgba(255,236,150,${.9*g})`); gr.addColorStop(.25,`rgba(255,214,110,${.45*g})`); gr.addColorStop(1,'rgba(255,214,110,0)');\n        ctx.globalAlpha=1; ctx.fillStyle=gr; ctx.beginPath(); ctx.arc(p.x,p.y,r*2.4,0,Math.PI*2); ctx.fill();\n      } else if(tipo==='corazones'){\n        p.y+=p.vy; p.x+=Math.sin(p.t*.02)*p.amp*dpr;\n        ctx.globalAlpha=Math.min(1,(p.y/H))*.7; ctx.fillStyle=p.c; heart(p.x,p.y,14*p.s);\n        if(p.y<-20*dpr) P[i]=make(false);\n      }\n    });\n    ctx.globalAlpha=1;\n    requestAnimationFrame(frame);\n  }\n  requestAnimationFrame(frame);\n})();\n<\/script>\n<script id=\"extras\">(function(){\n  /* Extras para todos los modelos: crédito detallisimos.com, momentos de XV, tiara y modo PDF */\n  const C=window.CFG||{}, $=id=>document.getElementById(id);\n  const esc=t=>String(t??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n  const h12=h=>{if(!h)return'';let[A,M]=h.split(':').map(Number);const ap=A>=12?'p.m.':'a.m.';A=A%12||12;return A+':'+String(M).padStart(2,'0')+' '+ap;};\n  const css=t=>{const s=document.createElement('style');s.textContent=t;document.head.appendChild(s);};\n\n  // Tiara sobre el nombre (modelos de XV)\n  const TIARA='<svg viewBox=\"0 0 120 60\" aria-hidden=\"true\"><path d=\"M8 52C20 40 22 22 22 14c8 10 14 16 22 18 2-12 8-22 16-28 8 6 14 16 16 28 8-2 14-8 22-18 0 8 2 26 14 38z\" style=\"fill:var(--m-mid);stroke:var(--m-lo)\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/>'\n    +'<path d=\"M8 52h104\" style=\"stroke:var(--m-lo)\" stroke-width=\"5\" stroke-linecap=\"round\"/><path d=\"M8 52h104\" style=\"stroke:var(--m-hi)\" stroke-width=\"2\" stroke-linecap=\"round\"/>'\n    +'<circle cx=\"60\" cy=\"4\" r=\"4.5\" style=\"fill:var(--m-hi)\"/><circle cx=\"22\" cy=\"12\" r=\"3.5\" style=\"fill:var(--m-hi)\"/><circle cx=\"98\" cy=\"12\" r=\"3.5\" style=\"fill:var(--m-hi)\"/>'\n    +'<path d=\"M60 22l7 9-7 9-7-9z\" style=\"fill:var(--fab-hi);stroke:#fff\" stroke-width=\"1\"/><circle cx=\"36\" cy=\"38\" r=\"4\" style=\"fill:var(--fab-glow)\"/><circle cx=\"84\" cy=\"38\" r=\"4\" style=\"fill:var(--fab-glow)\"/><\/svg>';\n  document.querySelectorAll('.tiara').forEach(t=>t.innerHTML=TIARA);\n\n  // Momentos especiales de XV\n  const box=$('tradiciones');\n  if(box){\n    const DEF=[{\"k\": \"entrada\", \"on\": false, \"texto\": \"Mi entrada\", \"hora\": \"\"}, {\"k\": \"vals\", \"on\": true, \"texto\": \"Vals con papá\", \"hora\": \"\"}, {\"k\": \"zapatilla\", \"on\": true, \"texto\": \"Cambio de zapatillas\", \"hora\": \"\"}, {\"k\": \"tiara\", \"on\": true, \"texto\": \"Coronación\", \"hora\": \"\"}, {\"k\": \"muneca\", \"on\": true, \"texto\": \"La última muñeca\", \"hora\": \"\"}, {\"k\": \"velas\", \"on\": false, \"texto\": \"Ceremonia de las 15 velas\", \"hora\": \"\"}, {\"k\": \"brindis\", \"on\": true, \"texto\": \"Brindis\", \"hora\": \"\"}, {\"k\": \"pastel\", \"on\": false, \"texto\": \"Partida del pastel\", \"hora\": \"\"}, {\"k\": \"sorpresa\", \"on\": false, \"texto\": \"Baile sorpresa\", \"hora\": \"\"}];\n    const T=(Array.isArray(C.tradiciones)?C.tradiciones:DEF).filter(x=>x&&x.on&&(x.texto||'').trim());\n    const sec=box.closest('[data-sec]');\n    if(!T.length){ if(sec) sec.hidden=true; }\n    else{\n      const st='fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"';\n      const I={\n        entrada:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M12 42V18a12 12 0 0 1 24 0v24\"/><path d=\"M8 42h32M24 42V30\"/><path d=\"M38 8l1.5 3 3 1.5-3 1.5L38 17l-1.5-3-3-1.5 3-1.5z\"/><\/svg>`,\n        vals:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M18 34V10l20-4v24\"/><circle cx=\"13\" cy=\"34\" r=\"5\"/><circle cx=\"33\" cy=\"30\" r=\"5\"/><path d=\"M18 16l20-4\"/><\/svg>`,\n        zapatilla:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M6 34c6 0 10-2 14-8l6-8c2-3 6-3 8 0 4 6 8 10 10 16v4H22\"/><path d=\"M8 34v8M6 34h16\"/><path d=\"M30 20l-4 8\"/><\/svg>`,\n        tiara:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M6 36l4-20 9 10 5-16 5 16 9-10 4 20z\"/><path d=\"M6 40h36\"/><circle cx=\"24\" cy=\"8\" r=\"2\"/><\/svg>`,\n        muneca:`<svg viewBox=\"0 0 48 48\" ${st}><circle cx=\"24\" cy=\"11\" r=\"6\"/><path d=\"M18 9c2-4 10-4 12 0\"/><path d=\"M20 18l-2 6 6 2 6-2-2-6\"/><path d=\"M18 24L10 42h28l-8-18\"/><path d=\"M14 34h20\"/><\/svg>`,\n        velas:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M12 42V24h6v18M21 42V18h6v24M30 42V24h6v18M8 42h32\"/><path d=\"M15 18c-2-2 0-5 0-6 2 2 2 4 0 6zM24 12c-2-2 0-5 0-6 2 2 2 4 0 6zM33 18c-2-2 0-5 0-6 2 2 2 4 0 6z\"/><\/svg>`,\n        brindis:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M10 8h10l-1 10a4 4 0 0 1-8 0z\" transform=\"rotate(-12 15 14)\"/><path d=\"M28 8h10l-1 10a4 4 0 0 1-8 0z\" transform=\"rotate(12 33 14)\"/><path d=\"M14 22l-2 14M34 22l2 14M8 38h8M32 38h8\"/><path d=\"M22 6l2-3 2 3\"/><\/svg>`,\n        pastel:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M8 42h32M10 42V30h28v12M14 30v-8h20v8\"/><path d=\"M10 34c3 2 5 2 7 0s5-2 7 0 5 2 7 0 5-2 7 0\"/><path d=\"M24 22v-6M24 12c-2-2 0-5 0-6 2 2 2 4 0 6z\"/><\/svg>`,\n        sorpresa:`<svg viewBox=\"0 0 48 48\" ${st}><path d=\"M24 4l5 11 12 1-9 8 3 12-11-6-11 6 3-12-9-8 12-1z\"/><path d=\"M6 42l4-4M42 42l-4-4\"/><\/svg>`\n      };\n      box.innerHTML=T.map(x=>`<li class=\"trad\"><span class=\"ti\" aria-hidden=\"true\">${I[x.k]||I.sorpresa}<\/span><b>${esc(x.texto)}<\/b>${x.hora?`<small>${esc(h12(x.hora))}<\/small>`:''}<\/li>`).join('');\n      css(`.trads{list-style:none;margin:8px 0 0;padding:0;width:100%;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 12px}\n.trad{display:flex;flex-direction:column;align-items:center;gap:6px;text-align:center}\n.trad .ti{width:66px;height:66px;border-radius:50%;display:grid;place-items:center;color:var(--btn);background:color-mix(in srgb,var(--paper-hi) 85%,transparent);border:1.5px solid var(--m-mid);box-shadow:0 0 0 4px color-mix(in srgb,var(--m-hi) 25%,transparent),0 8px 16px rgba(var(--sh),.1)}\n.trad .ti svg{width:34px;height:34px}\n.trad b{font-family:var(--f-script);font-weight:400;font-size:1.55rem;line-height:1.05;color:var(--ink-dark)}\n.trad small{font-family:var(--f-caps);font-variant-caps:all-small-caps;letter-spacing:.14em;font-size:.95rem;color:var(--ink)}\n.trads li:last-child:nth-child(odd){grid-column:1/-1}`);\n    }\n  }\n  css(`.tiara{width:84px;margin:0 auto -4px;filter:drop-shadow(0 3px 4px rgba(var(--sh),.2))}.tiara svg{width:100%;height:auto;display:block}`);\n\n  // Crédito\n  if(C.credito!==false){\n    const host=document.querySelector('main')||document.querySelector('.page')||document.querySelector('.card .content')||document.querySelector('.stage')||document.body;\n    const d=document.createElement('div');\n    d.className='dtl-credit';\n    d.innerHTML='<a href=\"https://detallisimos.com\" target=\"_blank\" rel=\"noopener\">Invitación digital · <b>detallisimos.com<\/b><\/a>';\n    host.appendChild(d);\n    css(`.dtl-credit{position:relative;z-index:2;text-align:center;padding:30px 16px 10px;font:12px/1.4 system-ui,-apple-system,sans-serif;letter-spacing:.06em;opacity:.65}\n.dtl-credit a{color:inherit;text-decoration:none}.dtl-credit b{font-weight:700}`);\n  }\n\n  // Modo PDF\n  if(C._print){\n    css(`#intro,.intro,canvas,.fab,#note,[data-sec=\"musica\"],.sky,.stars,#sky,#stars,#confetti,#petals{display:none!important}\n*,*::before,*::after{animation:none!important;transition:none!important}\n.rv{opacity:1!important;transform:none!important}\nhtml,body{-webkit-print-color-adjust:exact;print-color-adjust:exact}\nbody.locked{overflow:visible!important}\n.gal{flex-wrap:wrap;overflow:visible!important}.gal figure{flex:0 0 46%!important}`);\n    document.body.classList.remove('locked');\n    const cd=$('cd'); if(cd){ const bx=cd.closest('[aria-live]')||cd.parentElement.parentElement; bx.style.display='none'; }\n  }\n})();\n<\/script>\n<\/body>\n<\/html>\n";
